export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={rotate:'M20 7a8 8 0 0 0-14-2L3 8M3 3v5h5M4 17a8 8 0 0 0 14 2l3-3M21 21v-5h-5',crown:'M3 6l5 4 4-7 4 7 5-4-2 13H5ZM5 22h14',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',bolt:'m13 2-9 12h7l-1 8 10-13h-7l1-7',expand:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',world:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',file:'M14 2H5v20h14V7ZM14 2v6h5M8 12h8M8 16h6',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM12 2v4M12 18v4M2 12h4M18 12h4',seal:'m12 2 3 3 4 1 1 4 2 3-3 3-1 4-4 1-3-2-4-1-1-4-2-3 3-3 1-4ZM8 12l3 3 5-6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 6v6l4 2',arrow:'M5 12h14M13 6l6 6-6 6',plane:'m22 2-7 20-4-9L2 9 22 2ZM11 13 22 2',ghost:'M5 21V9a7 7 0 0 1 14 0v12l-4-3-3 3-3-3-4 3ZM9 9v2M15 9v2',scan:'M8 3H3v5M16 3h5v5M21 16v5h-5M8 21H3v-5M6 12h12M12 7v10',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',terminal:'M3 4h18v16H3ZM6 8l4 4-4 4M12 16h5',cuffs:'M10 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM22 10a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM10 14l4-4',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z',plus:'M12 4v16M4 12h16',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6ZM8 12l3 3 5-6',radar:'M21 12a9 9 0 1 1-9-9M12 12 21 3M16 12a4 4 0 1 1-4-4',case:'M3 7h18v14H3ZM8 7V3h8v4M3 12h18M10 12v3h4v-3',lock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0v4M12 14v3',unlock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0M12 14v3',drone:'M8 8h8v8H8ZM8 8 4 4M16 8l4-4M8 16l-4 4M16 16l4 4M1 4h6M17 4h6M1 20h6M17 20h6',check:'M4 12l5 5L20 6',close:'m6 6 12 12M6 18 18 6',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM9 9a3 3 0 1 1 4 3l-1 2M12 17v.2',chevron:'m8 4 8 8-8 8',save:'M4 3h14l3 3v15H3V3ZM7 3v6h10V3M7 21v-8h10v8',logout:'M9 3H3v18h6M10 12h12M17 7l5 5-5 5'};
