export function icon(id){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.target}"/></svg>`;}
export function button(text,cmd,cls='',extra=''){return `<button class="btn ${cls}" data-cmd="${cmd}" ${extra}>${text}</button>`;}
export const flag=id=>`<span class="country-code" title="${id}"><img src="./assets/flags/${id.toLowerCase()}.svg" alt="${id}" width="39" height="29"></span>`;
export function originNationalities(a){const original=ROSTER.find(r=>r.id===(a.templateId||a.id));return (original?.nationalities||[]).filter(id=>COUNTRY[id]);}
export function nationalityFlags(a){return `<span class="origin-nationalities">${originNationalities(a).map(id=>`<img src="./assets/flags/${id.toLowerCase()}.svg" alt="Nationalité : ${esc(COUNTRY[id].name)}" title="Nationalité : ${esc(COUNTRY[id].name)}" width="26" height="19">`).join('')}</span>`;}
export function nationalities(a){return nationalityFlags(a);}
export const portraitAsset=agent=>{const a={...agent,id:agent.templateId||agent.id};return ({p0:'iris',p12:'bishop',p13:'amber',p14:'lei',p15:'apero',p16:'mira',p17:'midnight',p18:'mercer',p19:'marlowe',p20:'nox',p21:'adler',p22:'dante',p23:'selin',p24:'rocket',p25:'alba',p26:'raven',p27:'link',p28:'viktor',p29:'monroe',p30:'tara'}[a.id] ? './assets/'+({p0:'iris',p12:'bishop',p13:'amber',p14:'lei',p15:'apero',p16:'mira',p17:'midnight',p18:'mercer',p19:'marlowe',p20:'nox',p21:'adler',p22:'dante',p23:'selin',p24:'rocket',p25:'alba',p26:'raven',p27:'link',p28:'viktor',p29:'monroe',p30:'tara'}[a.id])+'-portrait.webp'+(['p26','p27','p28','p29','p30'].includes(a.id)?'?v=185':['p15','p16'].includes(a.id)?'?v=43':'') : null);};
export const portraitBackgroundAsset=a=>['p27','p28','p29','p30'].includes(a.templateId||a.id)?'./assets/agent-portrait-background.webp?v=185':null;
export function portraitSvg(a,width,height){const asset=portraitAsset(a),background=portraitBackgroundAsset(a),n=a.portrait??0;return asset?`${background?`<image href="${background}" width="${width}" height="${height}" preserveAspectRatio="xMidYMid slice"/>`:''}<image href="${asset}" width="${width}" height="${height}" preserveAspectRatio="xMidYMid slice"/>`:`<svg width="${width}" height="${height}" viewBox="${n%3*362} ${Math.floor(n/3)*362} 362 362" preserveAspectRatio="xMidYMid slice"><image href="./assets/agents.png?v=3" width="1086" height="1448"/></svg>`;}
export function portrait(a,cls=''){if(portraitAsset(a))return `<div class="portrait ${portraitBackgroundAsset(a)?'portrait-cutout':''} ${cls}" role="img" aria-label="Portrait de ${esc(a.name)}"><img class="iris-portrait" src="${portraitAsset(a)}" alt=""></div>`;const n=a.portrait??0;return `<div class="portrait ${cls}" role="img" aria-label="Portrait de ${esc(a.name)}"><svg viewBox="${n%3*362} ${Math.floor(n/3)*362} 362 362" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="./assets/agents.png?v=3" width="1086" height="1448"/></svg></div>`;}
export function statlines(a){return `<div class="stats">${a.stats.map((n,i)=>`<div><span class="stat-label">${icon(['scan','target','shield'][i])} ${STAT_NAMES[i]}</span><i><b style="width:${n*10}%"></b></i><strong>${n}</strong></div>`).join('')}</div>`;}
export const TALENT_ICONS={chef:'crown',informatique:'terminal',enquete:'file',surveillance:'eye',contacts:'people',diplomatie:'seal',langues:'world',infiltration:'ghost',tactique:'target',combat:'cuffs',drones:'drone',secours:'plus',endurance:'shield'};
export const talentIcon=t=>icon(TALENT_ICONS[t]);
export function sortedTalents(a){return [...a.talents,...(a.chief?['chef']:[])].sort((x,y)=>TALENTS[x][0].localeCompare(TALENTS[y][0],'fr',{sensitivity:'base'}));}
export function talents(a){return `<div class="talents">${sortedTalents(a).map(t=>`<span title="${TALENTS[t][1]}">${talentIcon(t)}${TALENTS[t][0]}</span>`).join('')}</div>`;}
export function fatigue(a){return `<div class="fatigue"><span>${100-a.fatigue}/100 énergie</span><i role="meter" aria-label="Énergie : ${100-a.fatigue} sur 100 ; ${fatigueName(a.fatigue)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${100-a.fatigue}"><b class="${a.fatigue>=50?'warm':''}" style="width:${100-a.fatigue}%"></b></i></div>`;}
export function brand(){return `<div class="brand"><svg viewBox="0 0 54 48" aria-hidden="true"><path d="M3 3h48L27 44Z M12 8l23 24M24 8l16 17" fill="none" stroke="currentColor" stroke-width="2"/></svg><div>SIGMA <span>2040</span><small>CENTRE DE COMMANDEMENT</small></div></div>`;}
export function heading(k,title,sub='',right=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`;}
export const formatScore=n=>Number.isInteger(n)?n:n.toFixed(1);
